using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "TriggerEffectCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/TriggerEffectCustomDescription", order = 0)]
public class TriggerEffectCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		TriggerEffectAction triggerEffectAction = battleAction as TriggerEffectAction;
		string rawLocalizedDescription = GetRawLocalizedDescription(battleAction);
		if (triggerEffectAction.DecreaseEffect)
		{
			int decreaseEffectAmount = triggerEffectAction.DecreaseEffectAmount;
			if (triggerEffectAction.UseHalfOfTheEffect)
			{
				return Smart.Format(rawLocalizedDescription, triggerEffectAction.RoundedUp ? base.localizationManager.GetLocalizedRoundedUp() : base.localizationManager.GetLocalizedRoundedDown(), base.localizationManager.GetLocalizedThenDecreaseEffect(triggerEffectAction.Effect, decreaseEffectAmount));
			}
			return Smart.Format(rawLocalizedDescription, base.localizationManager.GetLocalizedThenDecreaseEffect(triggerEffectAction.Effect, decreaseEffectAmount));
		}
		return rawLocalizedDescription;
	}
}
